<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Authoring;use InvalidArgumentException;final class WorkflowDraftService{public function __construct(private WorkflowDraftRepository$repository,private WorkflowDraftValidator$validator){}public function create(string$key,array$input,string$organizationId,int$userId,bool$mayCreatePlatform):array{$key=trim($key);if($key===''||strlen($key)>191){throw new InvalidArgumentException('A valid idempotency key is required.');}$draft=$this->validator->normalize($input);if($draft['scope']==='platform'){if(!$mayCreatePlatform){throw new InvalidArgumentException('Platform workflow creation is not permitted.');}$draft['organization_id']=null;$draft['scope_key']='platform';}else{if($organizationId===''){throw new InvalidArgumentException('An active organization context is required.');}$draft['organization_id']=$organizationId;$draft['scope_key']='organization:'.$organizationId;}$fingerprint=hash('sha256',wp_json_encode([$draft,$userId]));return$this->repository->create($key,$fingerprint,$draft,$userId);}}
